        const amt = $('#frm #f_amount');
        return amt && moneyVal(amt) !== 350000
          ? { sel: '#f_amount', mh: 'مبلغ را از ۳۵۰ به ۳۵۰٬۰۰۰ تومان درست کنید؛ زیر کادر باید «سیصد و پنجاه هزار تومان» را بخوانید.' }
          : tutorSubmit('مبلغ درست شد. دکمهٔ «ذخیره» را بزنید.');
      }
      const sm = tutorStrayModal(); if (sm) return sm;
      const pg = tutorOnPage('expenses'); if (pg) return pg;
      const e = tutorToolExpense();
      return { sel: `button[data-edit="${e ? e.id : ''}"]`, hint: `ردیف «${e ? e.description : 'بیل نو'}» را پیدا کنید (مبلغ فعلی ${e ? fmt(e.amount) : '۳۵۰'} تومان) و دکمهٔ مداد کنارش را بزنید.` };
    }

