guard.dynamicSource:
(key, v) {
      if (key !== 'adjustments') return '';
      const u = P().users.find(x => x.id === v.userId);
      if (v.kind === 'settle' && (!u || u.type !== 'master')) return 'تسویه نقدی فقط برای اوستا ثبت می‌شود.';   // same rule and wording as the real validator
      if (v.kind !== 'settle') return 'نوع را روی «تسویه نقدی (فقط اوستا)» بگذارید.';
      if (v.userId !== TUTOR_KAZEM) return 'در این گام تسویه برای اوستا کاظم است.';
      return tutorExact(v, 1500000);
    }

