guard.dynamicSource:
(key, v) {
      if (key !== 'users') return '';
      if (v.type !== 'apprentice') return 'حسن در این تمرین «شاگرد» است؛ نوع را روی «شاگرد» بگذارید.';
      if (normFa(v.name).indexOf('حسن') < 0) return 'اسم را «حسن» نگه دارید تا گام‌های بعد با هم جور باشد.';
