aim.dynamicSource:
() {
      const h = tutorHassan();
      if (!h) {
        return tutorCrudAim('users', {
          okMh: 'اسم «حسن» و نوع «شاگرد» آماده است. «ذخیره» را بزنید؛ برای او نرخ دستمزد نمی‌گذاریم.',
          check: () => tutorSel('f_type', 'apprentice', 'نوع را روی «شاگرد» بگذارید.'),
          open: () => tutorOnPage('users') || { sel: '#crudAdd', hint: 'دکمهٔ «کاربر جدید» را بزنید.' }
        });
      }
      if (P().wages.some(w => w.userId === h.id)) return { sel: tutorNav('wages'), hint: 'برای حسن نرخ ثبت شده، ولی این گام می‌خواهد نرخ نداشته باشد. از «دستمزدها» نرخ حسن را پاک کنید.' };
      return tutorAttAim(h.id, 'full');
    }

