      try { const it = sanityCheck().items.find(x => x.sev === 'error'); msg = it ? it.msg : ''; } catch (e) { /* ignore */ }
      return `قرمز شد، دقیقاً همان‌جا که انتظار داشتید: «${msg || 'حضور ثبت شده اما هیچ نرخ دستمزدی تعریف نشده'}». برخلاف گام سلامت فصل ۱ که همه‌چیز سبز بود، این‌جا اپ جلوی یک اشتباه واقعی را قبل از تسویه گرفت.`;
    }

